import json
p=[3,5,7,9,1]
phases={3:0,4:1,5:2,6:3,7:4,8:0,9:2,10:3,11:3,12:4}
for r in range(13,28): phases[r]=(r-13)%5
out=[]
for r in range(28):
    if r==0: row=[1]*28
    elif r==1: row=[1]*28
    elif r==2: row=[1,1]+[4]*26
    else:
        row=[1,1,4]+[p[(phases[r]+c-3)%5] for c in range(3,28)]
        if r==3:
            row[4]=2; row[5]=1
        elif r==4:
            row[3]=2
        elif r==5:
            row[3]=1
    out.append(row)
assert all(len(x)==28 for x in out) and len(out)==28
print(json.dumps(out,separators=(',',':')))
